namespace Beep.OilandGas.Models.Data.Accounting;
public sealed record CompanyFxRateFacts(string Id,string Version,string BookId,string SourceCurrency,string TargetCurrency,decimal Rate,int RateDecimals,string Direction,DateTime QuoteDate,DateTime EffectiveFrom,DateTime EffectiveThrough,DateTime ObservedAtUtc,string Provider,string Provenance,string AuthorityReference,string AllocationPolicy,string BookNativeRevision,string CreatedBy,DateTime CreatedAtUtc,string NativeRevision);
public sealed record CompanyFxRateWindow(string Version,DateTime From,DateTime Through)
{
    public const string CurrentVersion="DATE_WINDOW_V2";
    public void Require(){CompanyGLMappingReview.RequireDate(From);CompanyGLMappingReview.RequireDate(Through);if(Version!=CurrentVersion || From>Through)throw new InvalidOperationException("An explicit supported inclusive FX review window is required.");}
}
public sealed record CompanyFxRateReview(CompanyLedgerBookReview Books,string BookId,string SourceCurrency,DateTime ReviewDate,IReadOnlyList<CompanyFxRateFacts> Rates,string Revision)
{
    public const int MaximumRates=128;
    // Absence identifies an original whole-pair receipt; it never means today's date or a new scoped review.
    [JsonIgnore(Condition=JsonIgnoreCondition.WhenWritingNull)]public CompanyFxRateWindow? Window{get;init;}
    public static CompanyFxRateReview Create(CompanyLedgerBookReview books,string book,string currency,DateTime date,IEnumerable<FX_RATE> records,CompanyFxRateWindow? window=null)
    {
        books.Require(books.Company,books.ActorUserId);var configured=books.Books.SingleOrDefault(row=>row.BookId==book) ??throw new InvalidOperationException("The original company book is unconfigured.");Currency(currency);CompanyGLMappingReview.RequireDate(date);var rows=records.Take(MaximumRates+1).ToArray();if(rows.Length>MaximumRates || rows.Any(row=>row is null))throw new InvalidOperationException("The complete bounded original rate registry is unavailable.");
        foreach(var row in rows){var command=CompanyFxRateProof.Require(row).Command;if(command.Company!=books.Company || command.Book!=configured || command.SourceCurrency!=currency)throw new InvalidOperationException("A native rate belongs to another company/book/source currency or book version.");}
        var facts=rows.Select(CompanyFxRateProof.CanonicalRow).Select(row=>new CompanyFxRateFacts(row.FX_RATE_ID,row.RATE_VERSION!,row.BOOK_ID!,row.FROM_CURRENCY,row.TO_CURRENCY,row.RATE!.Value,row.RATE_DECIMALS!.Value,row.RATE_DIRECTION!,row.RATE_DATE!.Value,row.EFFECTIVE_FROM!.Value,row.EFFECTIVE_THROUGH!.Value,row.OBSERVED_AT_UTC!.Value,row.PROVIDER_NAME!,row.PROVENANCE_REFERENCE!,row.AUTHORITY_REFERENCE!,row.ALLOCATION_POLICY!,row.BOOK_NATIVE_REVISION!,row.ROW_CREATED_BY,row.ROW_CREATED_DATE!.Value,ProcessDefinitionRevision.FromJson(JsonSerializer.Serialize(row)))).OrderBy(row=>row.EffectiveFrom).ThenBy(row=>row.Id,StringComparer.Ordinal).ToArray();var result=new CompanyFxRateReview(CompanyInventorySourceReview.Copy(books),book,currency,date,facts,string.Empty){Window=window is null?null:CompanyInventorySourceReview.Copy(window)};result=result with{Revision=Digest(result)};result.Require(books.Company,books.ActorUserId,book,currency,date);return CompanyInventorySourceReview.Copy(result);
    }
    public void Require(CompanyScope company,string actor,string book,string source,DateTime date)
    {
        if(Books is null || Rates is null || Rates.Count>MaximumRates || Rates.Any(row=>row is null))throw new InvalidOperationException("The complete original company FX review is unavailable.");Books.Require(company,actor);var configured=Books.Books.SingleOrDefault(row=>row.BookId==book) ??throw new InvalidOperationException("The selected functional book is unavailable.");Currency(source);CompanyGLMappingReview.RequireDate(date);
        if(BookId!=book || SourceCurrency!=source || ReviewDate!=date || Rates.Select(row=>row.Id).Distinct(StringComparer.Ordinal).Count()!=Rates.Count || Rates.Select(row=>row.Version).Distinct(StringComparer.Ordinal).Count()!=Rates.Count || !Rates.SequenceEqual(Rates.OrderBy(row=>row.EffectiveFrom).ThenBy(row=>row.Id,StringComparer.Ordinal)))throw new InvalidOperationException("The complete FX source identity/order changed.");
        if(Window is {} window){window.Require();if(date<window.From || date>window.Through || Rates.Any(row=>row.EffectiveFrom>window.Through || row.EffectiveThrough<window.From))throw new InvalidOperationException("The provider supplied rates outside the explicit original review window.");}
        foreach(var row in Rates){BillingPolicyValues.Intent(row.Id);Values(row.Version,row.SourceCurrency,row.TargetCurrency,row.Rate,row.RateDecimals,row.Direction,row.QuoteDate,row.EffectiveFrom,row.EffectiveThrough,row.ObservedAtUtc,row.Provider,row.Provenance,row.AuthorityReference,row.AllocationPolicy);BillingPolicyValues.Text(row.CreatedBy,128);BillingPolicyValues.Revision(row.NativeRevision);if(row.BookId!=book || row.SourceCurrency!=source || row.TargetCurrency!=configured.FunctionalCurrency || row.BookNativeRevision!=configured.NativeRevision || row.CreatedAtUtc.Kind!=DateTimeKind.Utc || row.CreatedAtUtc==default || row.ObservedAtUtc>row.CreatedAtUtc)throw new InvalidOperationException("The original functional book and native rate audit are unconfirmed.");}
        for(var index=1;index<Rates.Count;index++)if(Rates[index].EffectiveFrom<=Rates[index-1].EffectiveThrough)throw new InvalidOperationException("Company rate versions must have unambiguous nonoverlapping date ranges.");if(Revision!=Digest(this))throw new InvalidOperationException("The complete original FX registry changed.");
    }
    public CompanyFxRateFacts RequireApplicable(){Require(Books.Company,Books.ActorUserId,BookId,SourceCurrency,ReviewDate);return Rates.SingleOrDefault(row=>row.EffectiveFrom<=ReviewDate && row.EffectiveThrough>=ReviewDate) ??throw new InvalidOperationException("No recorded FX rate covers the explicit company calendar date. No rate or inverse rate is inferred.");}
    public void RequireWindow(DateTime from,DateTime through){Require(Books.Company,Books.ActorUserId,BookId,SourceCurrency,ReviewDate);if(Window is null || Window.From!=from || Window.Through!=through)throw new InvalidOperationException("Review the complete explicit original effective-date window first.");}
    public CompanyFxRateReview AsReader(string actor){Require(Books.Company,Books.ActorUserId,BookId,SourceCurrency,ReviewDate);var result=this with{Books=Books.AsReader(actor),Revision=string.Empty};result=result with{Revision=Digest(result)};result.Require(result.Books.Company,actor,BookId,SourceCurrency,ReviewDate);return CompanyInventorySourceReview.Copy(result);}
    internal static void Currency(string value){if(value is null || value.Length!=3 || value.Any(letter=>letter is <'A' or >'Z'))throw new InvalidOperationException("An explicit uppercase three-letter currency is required.");}
    internal static void Values(string version,string source,string target,decimal rate,int decimals,string direction,DateTime quote,DateTime from,DateTime through,DateTime observed,string provider,string provenance,string authority,string allocation)
    {
        BillingPolicyValues.Text(version,128);Currency(source);Currency(target);if(source==target || rate<=0 || decimals is <0 or >12 || decimal.Round(rate,decimals,MidpointRounding.ToEven)!=rate || direction!="TARGET_PER_SOURCE" || allocation!="LARGEST_REMAINDER")throw new InvalidOperationException("An explicit positive directed foreign rate, exact precision and allocation policy are required.");foreach(var value in new[]{quote,from,through})CompanyGLMappingReview.RequireDate(value);if(from>through || quote>from || observed.Kind!=DateTimeKind.Utc || observed==default)throw new InvalidOperationException("Explicit ordered quote/effective dates and UTC observation are required.");BillingPolicyValues.Text(provider,256);BillingPolicyValues.Text(provenance,2000);BillingPolicyValues.Text(authority,2000);
    }
    private static string Digest(CompanyFxRateReview value)=>ProcessDefinitionRevision.FromJson(JsonSerializer.Serialize(value with{Revision=string.Empty}));
}
public sealed record CompanyFxRateConfigurationCommand(string IntentId,CompanyScope Company,string ActorUserId,string Id,CompanyLedgerBookFacts Book,string SourceCurrency,string Version,decimal Rate,int RateDecimals,string Direction,DateTime QuoteDate,DateTime EffectiveFrom,DateTime EffectiveThrough,DateTime ObservedAtUtc,string Provider,string Provenance,string AuthorityReference,string AllocationPolicy,string Reason,string SourceRevision,string BindingRevision)
{
    public void Require(){PurchaseOrderOwnership.RequireScope(Company);BillingPolicyValues.Text(ActorUserId,128);BillingPolicyValues.Intent(IntentId);BillingPolicyValues.Intent(Id);BillingPolicyValues.Text(Reason,128);BillingPolicyValues.Revision(SourceRevision);BillingPolicyValues.Revision(BindingRevision);ArgumentNullException.ThrowIfNull(Book);CompanyLedgerBookReview.BookValues(Book.BookId,Book.Name,Book.FunctionalCurrency,Book.CurrencyDecimals,Book.RoundingPolicy,Book.CalendarId,Book.TimeZoneId);BillingPolicyValues.Revision(Book.NativeRevision);CompanyFxRateReview.Values(Version,SourceCurrency,Book.FunctionalCurrency,Rate,RateDecimals,Direction,QuoteDate,EffectiveFrom,EffectiveThrough,ObservedAtUtc,Provider,Provenance,AuthorityReference,AllocationPolicy);}
    public void Require(CompanyFxRateReview source){Require();if(source.Window is not null)source.RequireWindow(EffectiveFrom,EffectiveThrough);source.Require(Company,ActorUserId,Book.BookId,SourceCurrency,source.ReviewDate);if(source.Revision!=SourceRevision || source.Books.Books.SingleOrDefault(row=>row.BookId==Book.BookId)!=Book || source.Rates.Count>=CompanyFxRateReview.MaximumRates || source.Rates.Any(row=>row.Id==Id || row.Version==Version || row.EffectiveFrom<=EffectiveThrough && row.EffectiveThrough>=EffectiveFrom))throw new InvalidOperationException("The original rate source changed, is full or reserves this identity/version/effective interval.");}
    public FX_RATE CreateRow()=>new(){FX_RATE_ID=Id,OWNER_TENANT_ID=Company.TenantId,OWNER_COMPANY_BA_ID=Company.BusinessAssociateId,BOOK_ID=Book.BookId,FROM_CURRENCY=SourceCurrency,TO_CURRENCY=Book.FunctionalCurrency,RATE=Rate,RATE_DECIMALS=RateDecimals,RATE_DIRECTION=Direction,RATE_VERSION=Version,RATE_DATE=QuoteDate,EFFECTIVE_FROM=EffectiveFrom,EFFECTIVE_THROUGH=EffectiveThrough,OBSERVED_AT_UTC=ObservedAtUtc,PROVIDER_NAME=Provider,PROVENANCE_REFERENCE=Provenance,AUTHORITY_REFERENCE=AuthorityReference,ALLOCATION_POLICY=AllocationPolicy,BOOK_NATIVE_REVISION=Book.NativeRevision,ACTIVE_IND="Y",SOURCE=CompanyFxRateProof.Source,REMARK=Reason,PPDM_GUID=Guid.ParseExact(IntentId,"N").ToString()};
}
public sealed record CompanyFxRateConfigurationReview(CompanyFxRateReview Source,string BindingRevision){public void Require(CompanyScope company,string actor,string book,string source,DateTime date){Source.Require(company,actor,book,source,date);BillingPolicyValues.Revision(BindingRevision);}}
public sealed record CompanyFxRateConfigurationSubmission(CompanyFxRateConfigurationCommand Command,CompanyFxRateReview? Review);
public sealed record CompanyFxRateReceipt(CompanyFxRateConfigurationCommand Command,string RowRevision);
public static class CompanyFxRateProof
{
    public const string Source="COMPANY_FX_RATE_CONFIGURATION";
    public const int MaximumLength=262144;
    public static string Create(CompanyFxRateConfigurationCommand command,FX_RATE row){RequireFacts(command,row);var json=JsonSerializer.Serialize(new CompanyFxRateReceipt(command,Digest(row)));if(json.Length>MaximumLength)throw new InvalidOperationException("The complete rate receipt exceeds native capacity.");return json;}
    public static CompanyFxRateReceipt Require(FX_RATE row){if(string.IsNullOrWhiteSpace(row.CONFIGURATION_JSON) || row.CONFIGURATION_JSON.Length>MaximumLength)throw new InvalidOperationException("The original native company FX receipt is unavailable.");var receipt=JsonSerializer.Deserialize<CompanyFxRateReceipt>(row.CONFIGURATION_JSON) ??throw new InvalidOperationException("The native FX receipt is malformed.");if(receipt.Command is null)throw new InvalidOperationException("The original rate command is unavailable.");RequireFacts(receipt.Command,row);if(receipt.RowRevision!=Digest(row))throw new InvalidOperationException("The complete original recorded rate changed.");return receipt;}
    public static FX_RATE CanonicalRow(FX_RATE row){var copy=CompanyInventorySourceReview.Copy(row);if(copy.RATE is {} rate)copy.RATE=decimal.Parse(rate.ToString("G29",System.Globalization.CultureInfo.InvariantCulture),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture);return copy;}
    private static void RequireFacts(CompanyFxRateConfigurationCommand command,FX_RATE row){command.Require();CompanyGLAccountReview.RequireAudit(row);var expected=CanonicalRow(command.CreateRow());expected.ROW_CREATED_BY=row.ROW_CREATED_BY;expected.ROW_CREATED_DATE=row.ROW_CREATED_DATE;expected.ROW_CHANGED_BY=row.ROW_CHANGED_BY;expected.ROW_CHANGED_DATE=row.ROW_CHANGED_DATE;var actual=CanonicalRow(row);actual.CONFIGURATION_JSON=null;if(row.ROW_CREATED_BY!=command.ActorUserId || row.ROW_CHANGED_DATE is not null && row.ROW_CHANGED_BY!=command.ActorUserId || command.ObservedAtUtc>row.ROW_CREATED_DATE || JsonSerializer.Serialize(expected)!=JsonSerializer.Serialize(actual))throw new InvalidOperationException("Only the exact original rate facts and native producer audit are authorized.");}
    private static string Digest(FX_RATE row){var copy=CanonicalRow(row);copy.CONFIGURATION_JSON=null;return ProcessDefinitionRevision.FromJson(JsonSerializer.Serialize(copy));}
    public static bool IsCompanyMarked(FX_RATE row)=>row.OWNER_TENANT_ID is not null || row.OWNER_COMPANY_BA_ID is not null || row.BOOK_ID is not null || row.CONFIGURATION_JSON is not null || row.BOOK_NATIVE_REVISION is not null || row.RATE_VERSION is not null || row.EFFECTIVE_FROM is not null || row.EFFECTIVE_THROUGH is not null || row.OBSERVED_AT_UTC is not null || row.RATE_DECIMALS is not null || row.RATE_DIRECTION is not null || row.PROVIDER_NAME is not null || row.PROVENANCE_REFERENCE is not null || row.AUTHORITY_REFERENCE is not null || row.ALLOCATION_POLICY is not null;
}
